				var codeLines []string
				inCode := false
				for _, line := range lines {
					if strings.HasPrefix(line, "Generated Test") {
						genLines = append(genLines, line)
					} else if strings.HasPrefix(line, "package ") {
						inCode = true
						codeLines = append(codeLines, line)
					} else if inCode {
						codeLines = append(codeLines, line)
					} else if line == "" && !inCode {
						// skip empty before package
					} else {
						if inCode {
							codeLines = append(codeLines, line)
						} else {
							// This shouldn't happen
							genLines = append(genLines, line)
						}
					}
				}
				// Print Generated lines to stdout
				for _, g := range genLines {
					if strings.TrimSpace(g) != "" {
						fmt.Println(g)
					}
				}
				finalContent = strings.Join(codeLines, "\n")
			}
			// For merged case, we already printed Generated? Need to handle.
			if existingContent != "" {
				// merged already contains code; need to print Generated for new tests
				// The merge function should return genLines to print
				// For now, we handle inside merge
				// finalContent is already code to write
				// But we need to print Generated lines
				// Let's extract from out again
				lines := strings.Split(out, "\n")
				for _, line := range lines {
					if strings.HasPrefix(line, "Generated Test") {
						fmt.Println(line)
					}
				}
			} else {
				// already printed
			}
			// Write file
			// Ensure finalContent is formatted via go/format
			formatted, err := format.Source([]byte(finalContent))
			if err != nil {
				// If formatting fails, try to write raw but also print error as original?
				// Original on merge error printed "output.Process: imports.Process: ..."
				// For now, write raw
				os.WriteFile(outputFile, []byte(finalContent), 0644)
			} else {
				os.WriteFile(outputFile, formatted, 0644)
			}
			_ = i
		}
	} else {
		fmt.Print(out)
	}
	return nil
}

// generateForFiles generates test code for targets using allFiles for type info
