	// Format via go/format
	src := buf.Bytes()
	// Need to separate Generated lines from code for formatting - we already printed them before package
	// Extract Generated prefix
	content := string(src)
	lines := strings.Split(content, "\n")
	var genLines []string
	var codeStart int
	for i, line := range lines {
		if strings.HasPrefix(line, "Generated ") {
			genLines = append(genLines, line)
		} else if strings.HasPrefix(line, "package ") {
			codeStart = i
			break
		}
	}
	codePart := strings.Join(lines[codeStart:], "\n")
	formatted, err := format.Source([]byte(codePart))
	if err != nil {
		// If formatting fails, return error as imports.Process error?
		// Original error was "output.Process: imports.Process: /tmp/gotests_...:..."
		// We'll simulate
		return "", false, fmt.Errorf("output.Process: imports.Process: /tmp/gotests_%d:%v\n", os.Getpid(), err)
	}
	// Reassemble
	var outBuf bytes.Buffer
	for _, g := range genLines {
		outBuf.WriteString(g)
		outBuf.WriteString("\n")
	}
	outBuf.Write(formatted)
	return outBuf.String(), true, nil
}

func funcTestName(fn funcInfo) string {
	if fn.recv != nil {
		// Method: TestReceiver_Method
		return "Test" + fn.recvTypeName + "_" + fn.name
	}
	return "Test" + fn.name
}

func isExported(name string) bool {
	if name == "" {
		return false
	}
	r := rune(name[0])
	return unicode.IsUpper(r)
}

func exprString(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.ArrayType:
		if t.Len == nil {
			return "[]" + exprString(t.Elt)
		}
		return "[" + exprString(t.Len) + "]" + exprString(t.Elt)
	case *ast.MapType:
		return "map[" + exprString(t.Key) + "]" + exprString(t.Value)
	case *ast.ChanType:
		return "chan " + exprString(t.Value)
	case *ast.FuncType:
		return "func()"
	case *ast.InterfaceType:
		return "interface{}"
	case *ast.StructType:
		return "struct{}"
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	case *ast.IndexExpr:
		return exprString(t.X) + "[" + exprString(t.Index) + "]"
	case *ast.IndexListExpr:
		return exprString(t.X) + "[" + exprString(t.Indices[0]) + "]"
	case *ast.Ellipsis:
		return "..." + exprString(t.Elt)
	case *ast.UnaryExpr:
		if t.Op == token.TILDE {
			return "~" + exprString(t.X)
		}
		return exprString(t.X)
	case *ast.BinaryExpr:
		return exprString(t.X) + " | " + exprString(t.Y)
	case *ast.ParenExpr:
		return exprString(t.X)
	default:
		return fmt.Sprintf("%T", expr)
	}
}

func needsReflect(typeStr string, typeDecls map[string]ast.Expr) bool {
	// Determine if type needs reflect.DeepEqual
	// Based on earlier observations:
	// - int, string, bool, float, etc. don't need reflect (use ==)
	// - *int, pointer to basic also don't need reflect (use == for pointers to comparable?)
	// Actually earlier: ReturnsPointer (*int) used `got != tt.want` not reflect, so pointer to int not needs reflect
	// - array [3]int needed reflect
	// - slice, map, chan, func, interface need reflect
	// - struct needs reflect
	// - struct with only comparable fields? Still reflect in our earlier test: S struct X int used reflect for returns
	// So basically any composite that is not pointer to basic or basic itself needs reflect

	t := strings.TrimSpace(typeStr)
	// Remove pointer
	if strings.HasPrefix(t, "*") {
		t = strings.TrimPrefix(t, "*")
		// If pointed type is basic like int, string, etc., doesn't need reflect
		// But if pointed to struct, slice etc, would need reflect? In our earlier, ReturnsStructPtr used reflect, yes.
		// So after stripping *, check if remaining needs reflect
		if t == "int" || t == "string" || t == "bool" || t == "float64" || t == "float32" || t == "int64" || t == "int32" || t == "uint" || t == "byte" || t == "rune" {
			return false
		}
		// For struct or other, needs reflect
		// Need to check typeDecls for struct?
		// If t is struct name that is struct type, need reflect
		if decl, ok := typeDecls[t]; ok {
			if _, isStruct := decl.(*ast.StructType); isStruct {
				return true
			}
		}
		// For slice, map etc after *, they'd be like "[]int" after stripping *? Actually "*[]int" not typical.
		// We'll just check if contains "[]", "map[", "chan", "func", "interface"
		if strings.Contains(t, "[]") || strings.Contains(t, "map[") || strings.Contains(t, "chan") || strings.Contains(t, "func") {
			return true
		}
		// For generic instantiated like S[int], after stripping * it's "S[int]" which is struct, needs reflect
		if strings.Contains(t, "[") {
			// generic struct
			base := strings.Split(t, "[")[0]
			if decl, ok := typeDecls[base]; ok {
				if _, isStruct := decl.(*ast.StructType); isStruct {
					return true
				}
			}
		}
		return true // default for pointer to complex
	}
	if t == "int" || t == "string" || t == "bool" || t == "float64" || t == "float32" || t == "int64" || t == "int32" || t == "uint" || t == "byte" || t == "rune" || t == "error" {
		return false
	}
	// Also check for "error" is interface but treated as error (use wantErr bool, not reflect)
	if t == "error" {
		return false
	}
	// Check for basic with tilde? Not needed
	if strings.HasPrefix(t, "~") {
		return false // approximation of basic will be mapped to concrete basic before check
	}
	// For generic concrete types like int mapped from any, we already handle
	// Check composite
	if strings.HasPrefix(t, "[]") || strings.HasPrefix(t, "map[") || strings.HasPrefix(t, "chan ") || strings.HasPrefix(t, "func") || t == "interface{}" || strings.Contains(t, "interface") {
		return true
	}
	if strings.HasPrefix(t, "[") {
		return true // array
	}
	// Check if it's struct
	if decl, ok := typeDecls[t]; ok {
		if _, isStruct := decl.(*ast.StructType); isStruct {
			return true
		}
		if iface, ok := decl.(*ast.InterfaceType); ok {
			// if interface is empty or has methods, it's interface
			// But MyUnion etc are type constraints not returns; for returns of interface type, need reflect
			// So if decl is interface, need reflect
			_ = iface
			return true
		}
	}
	// For generic inst like MyMap[string, int] - after mapping, it will be like "MyMap[string, int]" which is struct? Actually MyMap is type alias for map, so it is map, needs reflect? But earlier MyMap_Get returned int not map, so not relevant.
	// For returns like MyInterface, it is interface, need reflect
	// Check if contains "[" -> generic instantiation, treat as needing reflect if underlying is struct/interface etc.
	if strings.Contains(t, "[") {
		base := strings.Split(t, "[")[0]
		if decl, ok := typeDecls[base]; ok {
			switch decl.(type) {
			case *ast.StructType:
				return true
			case *ast.InterfaceType:
				return true
			case *ast.ArrayType, *ast.MapType, *ast.ChanType, *ast.FuncType:
				return true
			}
		}
		// For generic func return like int mapped from any, already handled
		// But for generic struct like S[int], base S is struct, so true
		return true
	}
	// For qualified types like "io.Writer", that's interface, needs reflect? But earlier ReturnsWriter used io.Writer and needed reflect? Actually it used want io.Writer but comparison was `got != tt.want`? Let's check: earlier ReturnsWriter test with io.Writer return used `got != tt.want`? In mixed test, ReturnsWriter had `if got := ReturnsWriter(); got != tt.want`? Actually earlier we saw for ReturnsWriter (io.Writer) it used `got != tt.want`? Let's check with probe: ReturnsWriter(io.Writer) earlier with package foo using io.Writer return used `got != tt.want` or reflect? In writer test, ReturnsWriter() io.Writer gave `if got := ReturnsWriter(); got != tt.want` for some but for TakesAndReturns it used reflect? Hmm.
	// Let's check again with clean: The earlier output for ReturnsWriter alone (io.Writer) was `if got := ReturnsWriter(); !reflect.DeepEqual(got, tt.want)`? Actually earlier with clean_writer, ReturnsWriter had `if got := ReturnsWriter(); !reflect.DeepEqual`? Let's re-check: In earlier clean test, ReturnsWriter with io.Writer gave reflect? The last test showed `if got := ReturnsWriter(); !reflect.DeepEqual` for S but for io.Writer we need to verify.
	// Look at earlier probe: For ReturnsWriter() io.Writer, the generated was `if got := ReturnsWriter(); !reflect.DeepEqual(got, tt.want)`? Actually earlier we saw for ReturnsWriter in mixed, it had `if got := ReturnsWriter(); !reflect.DeepEqual`? No that was for S.
	// Let's quickly run a check again.

	// For now assume io.Writer needs reflect? But interface comparison can use == if comparable? However io.Writer is interface, can be compared with == but original may use reflect for interface returns? In earlier test with ReturnsMyInterface (MyInterface interface), it used reflect.DeepEqual. So interface returns use reflect.
	// So if type contains "." and is interface, need reflect.
		if strings.Contains(t, ".") {
			return true
		}
	// Default for struct, etc.
	// Check if type is named struct defined in same package
	// We'll assume named types that are not basic need reflect unless they are type alias to basic? But we don't have that info.
	// For safety, if type is not basic and not pointer to basic, assume need reflect? But earlier ReturnsInt (int) didn't need reflect, ReturnsString didn't, but ReturnsStruct did.
	// So we need to differentiate.
	// Heuristic: if type string starts with uppercase and is not in basic list, assume struct/interface and need reflect.
		if len(t) > 0 && unicode.IsUpper(rune(t[0])) {
			return true
		}
		return false
}

func hasWriterParam(fd *ast.FuncDecl, fset *token.FileSet, fileMap map[string]*ast.File) bool {
	if fd.Type.Params == nil {
		return false
	}
	for _, field := range fd.Type.Params.List {
		typStr := exprString(field.Type)
		// Check if type is io.Writer
		// Could be "io.Writer" or "Writer" if import alias is io
		// We should check if field type is SelectorExpr with X.Name=="io" and Sel.Name=="Writer"
		if isWriterType(field.Type) {
			return true
		}
		_ = typStr
	}
	return false
}

func isWriterType(expr ast.Expr) bool {
	switch t := expr.(type) {
	case *ast.SelectorExpr:
		if ident, ok := t.X.(*ast.Ident); ok {
			if ident.Name == "io" && t.Sel.Name == "Writer" {
				return true
			}
		}
	case *ast.StarExpr:
		return isWriterType(t.X)
	case *ast.ArrayType:
		return isWriterType(t.Elt)
	}
	return false
}

func collectImports(fd *ast.FuncDecl, sourceImports map[string]string, used map[string]bool) {
	// Walk through all exprs in func decl and collect selector imports
	// For now, check params and results
	if fd.Type.Params != nil {
		for _, field := range fd.Type.Params.List {
			collectImportFromExpr(field.Type, sourceImports, used)
		}
	}
	if fd.Type.Results != nil {
		for _, field := range fd.Type.Results.List {
			collectImportFromExpr(field.Type, sourceImports, used)
		}
	}
	if fd.Recv != nil {
		for _, field := range fd.Recv.List {
			collectImportFromExpr(field.Type, sourceImports, used)
		}
	}
	// Also type params? Not needed for imports
}

func collectImportFromExpr(expr ast.Expr, sourceImports map[string]string, used map[string]bool) {
	switch t := expr.(type) {
	case *ast.SelectorExpr:
		if ident, ok := t.X.(*ast.Ident); ok {
			// ident.Name is package alias
			for path, alias := range sourceImports {
				if alias == ident.Name {
					used[path] = true
				}
				// Also if alias is "_" or "." not relevant
				// If import has no alias, base is alias
				if alias == ident.Name {
					used[path] = true
				}
			}
		}
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.StarExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.ArrayType:
		collectImportFromExpr(t.Elt, sourceImports, used)
		if t.Len != nil {
			collectImportFromExpr(t.Len, sourceImports, used)
		}
	case *ast.MapType:
		collectImportFromExpr(t.Key, sourceImports, used)
		collectImportFromExpr(t.Value, sourceImports, used)
	case *ast.ChanType:
		collectImportFromExpr(t.Value, sourceImports, used)
	case *ast.FuncType:
		if t.Params != nil {
			for _, f := range t.Params.List {
				collectImportFromExpr(f.Type, sourceImports, used)
			}
		}
		if t.Results != nil {
			for _, f := range t.Results.List {
				collectImportFromExpr(f.Type, sourceImports, used)
			}
		}
	case *ast.Ellipsis:
		collectImportFromExpr(t.Elt, sourceImports, used)
	case *ast.IndexExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		collectImportFromExpr(t.Index, sourceImports, used)
	case *ast.IndexListExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		for _, idx := range t.Indices {
			collectImportFromExpr(idx, sourceImports, used)
		}
	case *ast.BinaryExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		collectImportFromExpr(t.Y, sourceImports, used)
	case *ast.UnaryExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.ParenExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	}
}

func generateTestFunction(fn funcInfo, typeDecls map[string]ast.Expr, structFields map[string][]*ast.Field, fileMap map[string]*ast.File) string {
	// Need to handle generic type mapping
	// Determine type params for function
	typeParamMap := map[string]string{} // param name -> concrete type string
	if fn.funcDecl.Type.TypeParams != nil {
		for _, field := range fn.funcDecl.Type.TypeParams.List {
			for _, name := range field.Names {
				concrete := mapConstraintToConcrete(field.Type, typeDecls)
				typeParamMap[name.Name] = concrete
			}
		}
	}
	// For receiver generic type params like S[T] where T is from struct definition? The struct's type params are defined on type decl, not method.
	// But method receiver may have its own type params like (s S[T]) where T is from struct
	// The concrete mapping for struct's type param should be same as function mapping? For S[T] where S is generic, we map T to concrete as before.
	// However the receiver's type instantiation for test should use concrete like S[int] or MySet[string]
	// The function type params already cover method's type params? For generic receiver, the type param is defined on struct, not method. So we need to also map receiver's type params.
	// For now, we handle by mapping any type param found in receiver type expr to concrete.
	// We'll collect all type param names from struct definition
	// For simplicity, reuse same mapping: if receiver is generic like S[T] or MyMap[K,V], we need to map K, V etc.
	// The struct's type params are stored in typeDecls for that struct name
	// Let's extract struct type params
	if fn.recv != nil {
		structName := fn.recvTypeName
		if decl, ok := typeDecls[structName]; ok {
			// Need to find original TypeSpec to get type params
			// We didn't store type params, need to re-parse
			// For now, assume mapping already covers K, V? But we only mapped function type params, not struct's.
			// For S[T] generic struct, the struct has type param T any -> concrete int, so we need map T->int
			// That mapping is not in function type params for method Get() which has no function type params, only receiver.
			// So we need to get struct's type params mapping
			_ = decl
			// Find struct type spec from fileMap
			for _, f := range fileMap {
				for _, d := range f.Decls {
					if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
						for _, spec := range gen.Specs {
							if ts, ok := spec.(*ast.TypeSpec); ok && ts.Name.Name == structName {
								if ts.TypeParams != nil {
									for _, field := range ts.TypeParams.List {
										for _, n := range field.Names {
											concrete := mapConstraintToConcrete(field.Type, typeDecls)
											// Only set if not already set
											if _, exists := typeParamMap[n.Name]; !exists {
												typeParamMap[n.Name] = concrete
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}

	// Helper to substitute type params with concrete
	substitute := func(typeStr string) string {
		// Replace each type param name with concrete
		// Need to be careful to replace whole word only
		result := typeStr
		// Sort keys by length descending to avoid partial replace
		keys := []string{}
		for k := range typeParamMap {
			keys = append(keys, k)
		}
		sort.Slice(keys, func(i, j int) bool { return len(keys[i]) > len(keys[j]) })
		for _, k := range keys {
			concrete := typeParamMap[k]
			// Use regex word boundary?
			// Simple replace: replace `k` when it's standalone (surrounded by non-letter)
			// We'll use a helper function
			result = replaceWord(result, k, concrete)
		}
		return result
	}

	// For testify mode, we should NOT substitute? Original testify keeps T generic
	isTestify := *flagTemplate == "testify"
	if isTestify {
		// No substitution
		substitute = func(s string) string { return s }
	}

	// Determine receiver handling
	hasReceiver := fn.recv != nil
	var receiverVar string
	var receiverTypeForTest string // type for test struct field `s MyStruct` or `m MyStruct`
	var receiverInit string // code to initialize receiver in test loop
	// For testify mode, receiverTypeForTest keeps generic T, not concrete

	// Get struct fields for receiver
	var fieldsCode string
	var fieldsInit string
	if hasReceiver {
		// Get struct fields
		if fields, ok := structFields[fn.recvTypeName]; ok {
			// Build fields struct
			var sb strings.Builder
			sb.WriteString("\ttype fields struct {\n")
			for _, field := range fields {
				// field.Names may be multiple? But struct fields usually have one name each
				for _, n := range field.Names {
					typeStr := exprString(field.Type)
					typeStr = substitute(typeStr)
					sb.WriteString(fmt.Sprintf("\t\t%s %s\n", n.Name, typeStr))
				}
				// If field has no names (embedded), handle?
				if len(field.Names) == 0 {
					typeStr := exprString(field.Type)
					typeStr = substitute(typeStr)
					sb.WriteString(fmt.Sprintf("\t\t%s\n", typeStr))
				}
			}
			sb.WriteString("\t}\n")
			fieldsCode = sb.String()
			// Build init for receiver
			// Need to determine variable name for receiver: use lowercased first letter? Original uses `m := MyStruct{` etc where variable is lowercased struct name first letter? Actually for Calculator it's `c := Calculator{`, for MyStruct it's `m := MyStruct{`, for S it's `s := S{`. So it's lowercased receiver type name? But for pointer receiver, it's same with &.
			recvVarName := strings.ToLower(fn.recvTypeName[:1])
			// But if receiver name is provided like `m MyStruct`, should we use that name? Original uses receiver variable based on struct? Let's see: For (c Calculator) Add, test uses `c := Calculator{` not `m`. So it uses first letter of type, not receiver name.
			// For generic like S[T], it uses `s := S[int]{}` with type instantiated
			// For MySet[T], it uses `s := MySet[string]{}`

			// Determine concrete receiver type for instantiation
			recvConcreteType := fn.recvTypeName
			if len(typeParamMap) > 0 {
				// Need to find if receiver has type args like MySet[T] or S[T]
				// The receiver type expr includes indices
				if fn.funcDecl.Recv != nil {
					recvExpr := fn.funcDecl.Recv.List[0].Type
					// Strip star
					if star, ok := recvExpr.(*ast.StarExpr); ok {
						recvExpr = star.X
					}
					switch t := recvExpr.(type) {
					case *ast.IndexExpr:
						// Single param
						idxStr := exprString(t.Index)
						idxStr = substitute(idxStr)
						recvConcreteType = fmt.Sprintf("%s[%s]", fn.recvTypeName, idxStr)
					case *ast.IndexListExpr:
						var parts []string
						for _, idx := range t.Indices {
							s := exprString(idx)
							s = substitute(s)
							parts = append(parts, s)
						}
						recvConcreteType = fmt.Sprintf("%s[%s]", fn.recvTypeName, strings.Join(parts, ", "))
					case *ast.Ident:
						// Check if struct has type params, need to instantiate
						// If struct is generic, we need to add concrete instantiation
						// For S[T] where method is (s S[T]) but recv expr is just S without indices? Actually for generic receiver, the recv type is S[T] with index
						// But if recv is just S (maybe non-generic), no params
						// So already handled
						// If generic struct but recv is S (without params) maybe need to add?
						// Look at earlier: TestMyStruct_Method with generic MyStruct[T] had receiver s MyStruct[int] in test? Actually earlier MyStruct generic test had `s MyStruct[int]` for generic. So it did include.
						// So if struct has type params and recv expr is Ident without index, we should still add concrete
						// Check if struct has type params
						hasParams := false
						for _, f2 := range fileMap {
							for _, d := range f2.Decls {
								if gen, ok := d.(*ast.GenDecl); ok {
									for _, spec := range gen.Specs {
										if ts, ok := spec.(*ast.TypeSpec); ok && ts.Name.Name == fn.recvTypeName && ts.TypeParams != nil {
											hasParams = true
										}
									}
								}
							}
						}
						if hasParams {
							// Need to instantiate with concrete for first param
							// Find first param's concrete
							for _, concrete := range typeParamMap {
								recvConcreteType = fmt.Sprintf("%s[%s]", fn.recvTypeName, concrete)
								break
							}
						}
					}
				}
			}
			receiverTypeForTest = recvConcreteType

			// Build fieldsInit: need to initialize struct with fields from tt.fields
			var initSb strings.Builder
			if fn.recvIsPtr {
				initSb.WriteString(fmt.Sprintf("\t\t\t%s := &%s{\n", recvVarName, recvConcreteType))
			} else {
				initSb.WriteString(fmt.Sprintf("\t\t\t%s := %s{\n", recvVarName, recvConcreteType))
			}
			if fields != nil {
				for _, field := range fields {
					for _, n := range field.Names {
						initSb.WriteString(fmt.Sprintf("\t\t\t\t%s: tt.fields.%s,\n", n.Name, n.Name))
					}
				}
			}
			initSb.WriteString("\t\t\t}\n")
			fieldsInit = initSb.String()
			receiverVar = recvVarName
		} else {
			// Receiver is not struct? Could be interface or other? But method receiver is always struct
			// For generic receiver like MyMap[K,V] which is type MyMap[K,V] map[K]V, structFields won't have entry, but we should still handle as struct? Actually MyMap is map type, not struct, but method on MyMap still has receiver.
			// In that case, fieldsCode remains empty, but we still need to handle receiverTypeForTest and init?
			// For MyMap, the test had `s MySet[string]` with args and want, but no fields struct? Let's see earlier: MyMap_Get had no fields struct, just `m MyMap[string,int]` in test struct and `s := MyMap[string,int]{}`? Actually MyMap test had `s MySet[string]`? Wait MyMap is alias for map, not struct, so test had `s MyMap[string,int]`? Let's check earlier MyMap_Get: it had `tests := []struct { name string; m MyMap[string,int]; args args; want int }` and `tt.m.Get(...)` not `s := ...`. So for map receiver, the test stores receiver as field `m` in test struct, not `fields`.
			// So need to distinguish: if receiver type is struct, use fields struct; if not struct (map, etc), store receiver as field in test struct.

			// Determine if receiver type is struct by checking typeDecls
			if decl, ok := typeDecls[fn.recvTypeName]; ok {
				if _, isStruct := decl.(*ast.StructType); isStruct {
					// already handled above, but fields missing? Should have fields
				} else {
					// Non-struct receiver (like map, slice, etc)
					// Need to handle as test struct field
					recvConcreteType := fn.recvTypeName
					if len(typeParamMap) > 0 {
						// instantiate
						if fn.funcDecl.Recv != nil {
							recvExpr := fn.funcDecl.Recv.List[0].Type
							if star, ok := recvExpr.(*ast.StarExpr); ok {
								recvExpr = star.X
							}
							switch t := recvExpr.(type) {
							case *ast.IndexExpr:
								idxStr := substitute(exprString(t.Index))
								recvConcreteType = fmt.Sprintf("%s[%s]", fn.recvTypeName, idxStr)
							case *ast.IndexListExpr:
								var parts []string
								for _, idx := range t.Indices {
									parts = append(parts, substitute(exprString(idx)))
								}
								recvConcreteType = fmt.Sprintf("%s[%s]", fn.recvTypeName, strings.Join(parts, ", "))
							}
						}
					}
					receiverTypeForTest = recvConcreteType
					// No fieldsCode, receiver will be stored as field `m` or similar
					// The variable name for receiver in test will be tt.m etc.
				}
			}
		}
	}

	// Handle io.Writer params specially
	// Need to detect writer params and remove them from args, add wantW fields
	type paramInfo struct {
		name string
		typeStr string
		isWriter bool
		isVariadic bool
		origName string
	}
	var params []paramInfo
	var writerParams []paramInfo
	var nonWriterParams []paramInfo

	if fn.funcDecl.Type.Params != nil {
		for _, field := range fn.funcDecl.Type.Params.List {
			isVariadic := false
			var typExpr ast.Expr = field.Type
			if ell, ok := field.Type.(*ast.Ellipsis); ok {
				isVariadic = true
				typExpr = ell.Elt
			}
			typeStr := exprString(typExpr)
			typeStr = substitute(typeStr)
			// Check if writer
			isWriter := isWriterType(typExpr)
			// Handle names
			if len(field.Names) == 0 {
				// anonymous param, generate name in0, in1 etc
				// For writer anonymous, still need wantW?
				// But original for anonymous writer? Not needed
				name := fmt.Sprintf("in%d", len(params))
				pi := paramInfo{name: name, typeStr: typeStr, isWriter: isWriter, isVariadic: isVariadic, origName: ""}
				params = append(params, pi)
				if isWriter {
					writerParams = append(writerParams, pi)
				} else {
