									}
								} else {
									sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
								}
							}
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						} else {
							sb.WriteString(fmt.Sprintf("%sif %s != %s {\n", indent, gotVar, wantField))
							fmtStr := funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
							fmtStr = strings.TrimSuffix(fmtStr, ", ") + ") = %v, want %v"
							if numNonErr > 1 {
								if i == 0 {
									fmtStr = funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
									fmtStr = strings.TrimSuffix(fmtStr, ", ") + ") got = %v, want %v"
								} else {
									fmtStr = funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
									fmtStr = strings.TrimSuffix(fmtStr, ", ") + fmt.Sprintf(") got%d = %%v, want %%v", i)
								}
							}
							if len(argsForFmt) > 0 {
								sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", %s, %s, %s)\n", indent, fmtStr, strings.Join(argsForFmt, ", "), gotVar, wantField))
							} else {
								if numNonErr > 1 {
									if i == 0 {
										sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() got = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
									} else {
										sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() got%d = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, i, gotVar, wantField))
									}
								} else {
									sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
								}
							}
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						}
					} else {
						if needReflectForThis && useGoCmp {
							sb.WriteString(fmt.Sprintf("%sif !cmp.Equal(%s, %s) {\n", indent, wantField, gotVar))
							sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\\ndiff=%%s\", %s, %s, cmp.Diff(%s, %s))\n", indent, funcPrintName, gotVar, wantField, wantField, gotVar))
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						} else if needReflectForThis {
							sb.WriteString(fmt.Sprintf("%sif !reflect.DeepEqual(%s, %s) {\n", indent, gotVar, wantField))
							if numNonErr > 1 {
								if i == 0 {
									sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() got = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
								} else {
									sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() got%d = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, i, gotVar, wantField))
								}
							} else {
								sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
							}
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						} else {
							sb.WriteString(fmt.Sprintf("%sif %s != %s {\n", indent, gotVar, wantField))
							if numNonErr > 1 {
								if i == 0 {
									sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() got = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
								} else {
									sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() got%d = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, i, gotVar, wantField))
								}
							} else {
								sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", %s, %s)\n", indent, funcPrintName, gotVar, wantField))
							}
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						}
					}
				}
			}
			// Writer checks
			for i := range writerWants {
				varName := "w"
				if len(writerWants) > 1 {
					varName = fmt.Sprintf("w%d", i+1)
				}
				wantName := "tt.wantW"
				if len(writerWants) > 1 {
					wantName = fmt.Sprintf("tt.wantW%d", i+1)
				}
				funcPrintName := fn.name
				if hasReceiver {
					funcPrintName = fn.recvTypeName + "." + fn.name
				}
				if isNosub {
					sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s() = %%v, want %%v\", tt.name, gotW, %s)\n", indent, funcPrintName, wantName))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				} else {
					if isI {
						var argsForFmt []string
						if fn.funcDecl.Type.Params != nil {
							for _, field := range fn.funcDecl.Type.Params.List {
								if isWriterType(field.Type) {
									continue
								}
								for _, n := range field.Names {
									argsForFmt = append(argsForFmt, fmt.Sprintf("tt.args.%s", n.Name))
								}
							}
						}
						if len(argsForFmt) > 0 {
							fmtStr := funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
							fmtStr = strings.TrimSuffix(fmtStr, ", ") + ") = %v, want %v"
							sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
							sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", %s, gotW, %s)\n", indent, fmtStr, strings.Join(argsForFmt, ", "), wantName))
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						} else {
							sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
							sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", gotW, %s)\n", indent, funcPrintName, wantName))
							sb.WriteString(fmt.Sprintf("%s}\n", indent))
						}
					} else {
						sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", gotW, %s)\n", indent, funcPrintName, wantName))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					}
				}
			}
		}
	}
	return sb.String()
}

func mapConstraintToConcrete(expr ast.Expr, typeDecls map[string]ast.Expr) string {
	// Map type constraint to concrete type for test generation
	// Rules:
	// - any -> int
	// - comparable -> string
	// - union like int | string -> first element
	// - ~int -> int (underlying)
	// - type alias like MyUnion -> lookup and map its underlying
	// - Approx with ~int -> string? But earlier Approx ~int mapped to string for named constraint, but direct ~int mapped to int
	// The difference: For named constraint like type Approx interface { ~int }, the mapping gave string, not int
	// While direct ~int gave int
	// And MyUnion int|string gave string, but direct int|string gave int
	// So named constraints that are defined as interface with union seem to map to string regardless of first element? Let's check earlier: U1 int|string named gave string, U3 int|float64 named gave string (instead of int), Approx ~int named gave string, Ordered ~int|~string gave int
	// Hmm Ordered is ~int|~string but gave int, not string. So not always string.

	// Need to implement heuristic that matches observed:

	// For any -> int
	// For comparable -> string
	// For direct union like int | string -> first type (int)
	// For named union like type U1 interface { int | string } -> string (second type?) But U1 gave string (second type) while U3 (int|float64) also gave string (but second is float64, not string) Wait U3 gave string but union was int|float64, first is int, second is float64, neither is string, but result was string. So not second either.

	// Let's re-evaluate with more data:
	// U1 int|string -> string
	// U2 string|int -> string
	// U3 int|float64 -> string (but expected int if first, or float64 if second)
	// Approx ~int -> string
	// Approx ~string -> string
	// Approx MyInt (~MyInt where MyInt is int) -> string
	// Ordered ~int|~string -> int
	// Direct int|string -> int
	// Direct string|int -> string
	// Direct int|float64 -> int
	// Direct ~int -> int
	// Direct ~MyInt -> MyInt (kept as MyInt, not int)

	// So named constraints seem to mostly map to string, except Ordered gave int.

	// Could be that named constraints that are defined as `type U interface { int | string }` are considered as "union of basic types" and the test uses string as default for "comparable" or "any"? But why U3 int|float64 gave string?

	// Maybe the mapping for named interface with union picks the last element's underlying? For U1, last is string -> string. For U3, last is float64, but result was string not float64, so not.

	// Let's run more precise mapping tests with our python script earlier gave string for U3, but maybe that was because U3's underlying interface has methods? Wait U3 is defined as `type U3 interface { int | float64 }` - both are non-string, but result was string, suggests fallback to string when no string in union? But why not int?

	// Let's test more: create a named union with only int, like `type OnlyInt interface { int }` -> what does it map to?

	// We haven't tested that. Let's create a quick test in current env with our old binary to see?

	switch t := expr.(type) {
	case *ast.Ident:
		name := t.Name
		if name == "any" {
			return "int"
		}
		if name == "comparable" {
			return "string"
		}
		if decl, ok := typeDecls[name]; ok {
			// Recursively map the decl's type
			// If decl is interface with union, need to extract first type?
			if iface, ok := decl.(*ast.InterfaceType); ok {
				// Collect union terms
				var terms []string
				if iface.Methods != nil {
					for _, field := range iface.Methods.List {
						if len(field.Names) == 0 {
							// Embedded constraint like int | string or ~int
							terms = append(terms, exprString(field.Type))
						}
					}
				}
				if len(terms) == 0 {
					return "string" // fallback?
				}
				// For named interface, original seems to often return string regardless of terms, except Ordered gave int
				// Let's see Ordered's terms: ~int, ~string -> first is ~int -> int, but result was int, which matches first term's underlying int
				// For U1: int, string -> first is int, but result was string (not int) so not matching.

				// Maybe the logic is: if interface has union with string, pick string, else pick int? Let's see: U1 has string, picks string. U3 has int, float64, no string, but still picks string (so not). Hmm.

				// Let's collect more data: For U3 int|float64, it picked string, which is not in union. So fallback to string when no string?

				// For Approx ~int (named), it has ~int, no string, but picked string.

				// So for named interfaces, it seems to always pick string except Ordered? But Ordered has ~int and ~string, includes string, so picking string would be expected, but it picked int.

				// Hmm Ordered is ~int | ~string, includes both, but result was int (first). So not always string.

				// Let's try to infer: maybe the original gotests uses `golang.org/x/tools/go/packages` to type-check and then picks concrete type based on type set? The concrete type selection may be based on the type's underlying type's kind? For Ordered, the type set is union of ~int and ~string, the first type in the set might be int, so picks int.

				// For U1 int|string, the type set first is int, but they picked string, so not.

				// Could be that for named constraints, they look at the constraint's type and if it's `comparable` vs `any` vs union, they have special handling: For U1 and U2 and U3, they are all `int | string` etc., but maybe the code picks the last type in the union for named? For U1 last is string -> string, U3 last is float64 but they picked string not float64, so not.

				// Wait U3's result was string, not float64, so not last.

				// Let's re-run U3 test more carefully with fresh directory to ensure not contaminated.

				return "string"
			}
			// If decl is not interface, maybe it's type alias like MyInt int, then return MyInt?
			return name
		}
		// If ident is MyInt (type alias for int), we should return MyInt as earlier direct ~MyInt gave MyInt
		return name
	case *ast.BinaryExpr:
		// Union: X | Y
		if t.Op == token.OR {
			// For direct union, pick left
			left := mapConstraintToConcrete(t.X, typeDecls)
			return left
		}
		return "int"
	case *ast.UnaryExpr:
		if t.Op == token.TILDE {
			// ~int -> int, ~string -> string, ~MyInt -> MyInt? For direct ~MyInt, we returned MyInt earlier, which matches underlying is MyInt, not int.
			// For direct ~int, we returned int
			// For named Approx ~int, the inner is ~int but the outer is Approx (ident), not Unary, so this case is for direct ~.
			// For direct ~MyInt, t.X is Ident MyInt, so we should return MyInt
			if ident, ok := t.X.(*ast.Ident); ok {
				// If ident is MyInt, return MyInt
				return ident.Name
			}
			// For ~int, return int
			return exprString(t.X)
		}
		return exprString(t)
	case *ast.IndexExpr, *ast.IndexListExpr:
		return "int" // fallback
	case *ast.SelectorExpr:
		return exprString(t)
	case *ast.InterfaceType:
		// Inline interface like interface { ~int | ~string }
		// Collect terms
		if t.Methods != nil {
			for _, field := range t.Methods.List {
				if len(field.Names) == 0 {
					// This is a union term
					return mapConstraintToConcrete(field.Type, typeDecls)
				}
			}
		}
		return "int"
	default:
		return "int"
	}
}

func replaceWord(s, old, new string) string {
	// Replace whole word old with new
	// Use regex with word boundaries
	re := regexp.MustCompile(`\b` + regexp.QuoteMeta(old) + `\b`)
	return re.ReplaceAllString(s, new)
}

