				if alias == ident.Name {
					used[path] = true
				}
			}
		}
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.StarExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.ArrayType:
		collectImportFromExpr(t.Elt, sourceImports, used)
		if t.Len != nil {
			collectImportFromExpr(t.Len, sourceImports, used)
		}
	case *ast.MapType:
		collectImportFromExpr(t.Key, sourceImports, used)
		collectImportFromExpr(t.Value, sourceImports, used)
	case *ast.ChanType:
		collectImportFromExpr(t.Value, sourceImports, used)
	case *ast.FuncType:
		if t.Params != nil {
			for _, f := range t.Params.List {
				collectImportFromExpr(f.Type, sourceImports, used)
			}
		}
		if t.Results != nil {
			for _, f := range t.Results.List {
				collectImportFromExpr(f.Type, sourceImports, used)
			}
		}
	case *ast.Ellipsis:
		collectImportFromExpr(t.Elt, sourceImports, used)
	case *ast.IndexExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		collectImportFromExpr(t.Index, sourceImports, used)
	case *ast.IndexListExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		for _, idx := range t.Indices {
			collectImportFromExpr(idx, sourceImports, used)
		}
	case *ast.BinaryExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		collectImportFromExpr(t.Y, sourceImports, used)
	case *ast.UnaryExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.ParenExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	}
}

func generateTestFunction(fn funcInfo, typeDecls map[string]ast.Expr, structFields map[string][]*ast.Field, fileMap map[string]*ast.File) string {
	// Need to handle generic type mapping
	// Determine type params for function
	typeParamMap := map[string]string{} // param name -> concrete type string
	if fn.funcDecl.Type.TypeParams != nil {
		for _, field := range fn.funcDecl.Type.TypeParams.List {
			for _, name := range field.Names {
				concrete := mapConstraintToConcrete(field.Type, typeDecls)
				typeParamMap[name.Name] = concrete
			}
		}
	}
	// For receiver generic type params like S[T] where T is from struct definition? The struct's type params are defined on type decl, not method.
	// But method receiver may have its own type params like (s S[T]) where T is from struct
	// The concrete mapping for struct's type param should be same as function mapping? For S[T] where S is generic, we map T to concrete as before.
	// However the receiver's type instantiation for test should use concrete like S[int] or MySet[string]
	// The function type params already cover method's type params? For generic receiver, the type param is defined on struct, not method. So we need to also map receiver's type params.
	// For now, we handle by mapping any type param found in receiver type expr to concrete.
	// We'll collect all type param names from struct definition
	// For simplicity, reuse same mapping: if receiver is generic like S[T] or MyMap[K,V], we need to map K, V etc.
	// The struct's type params are stored in typeDecls for that struct name
	// Let's extract struct type params
	if fn.recv != nil {
		structName := fn.recvTypeName
		if decl, ok := typeDecls[structName]; ok {
			// Need to find original TypeSpec to get type params
			// We didn't store type params, need to re-parse
			// For now, assume mapping already covers K, V? But we only mapped function type params, not struct's.
			// For S[T] generic struct, the struct has type param T any -> concrete int, so we need map T->int
			// That mapping is not in function type params for method Get() which has no function type params, only receiver.
			// So we need to get struct's type params mapping
			_ = decl
			// Find struct type spec from fileMap
			for _, f := range fileMap {
				for _, d := range f.Decls {
					if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
						for _, spec := range gen.Specs {
							if ts, ok := spec.(*ast.TypeSpec); ok && ts.Name.Name == structName {
								if ts.TypeParams != nil {
									for _, field := range ts.TypeParams.List {
										for _, n := range field.Names {
											concrete := mapConstraintToConcrete(field.Type, typeDecls)
											// Only set if not already set
											if _, exists := typeParamMap[n.Name]; !exists {
												typeParamMap[n.Name] = concrete
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}

	// Helper to substitute type params with concrete
	substitute := func(typeStr string) string {
		// Replace each type param name with concrete
		// Need to be careful to replace whole word only
		result := typeStr
		// Sort keys by length descending to avoid partial replace
		keys := []string{}
		for k := range typeParamMap {
			keys = append(keys, k)
		}
		sort.Slice(keys, func(i, j int) bool { return len(keys[i]) > len(keys[j]) })
		for _, k := range keys {
			concrete := typeParamMap[k]
			// Use regex word boundary?
			// Simple replace: replace `k` when it's standalone (surrounded by non-letter)
			// We'll use a helper function
			result = replaceWord(result, k, concrete)
		}
		return result
	}

	// For testify mode, we should NOT substitute? Original testify keeps T generic
	isTestify := *flagTemplate == "testify"
	if isTestify {
		// No substitution
		substitute = func(s string) string { return s }
	}

	// Determine receiver handling
	hasReceiver := fn.recv != nil
	var receiverVar string
	var receiverTypeForTest string // type for test struct field `s MyStruct` or `m MyStruct`
	var receiverInit string // code to initialize receiver in test loop
	// For testify mode, receiverTypeForTest keeps generic T, not concrete

	// Get struct fields for receiver
	var fieldsCode string
	var fieldsInit string
	if hasReceiver {
		// Get struct fields
		if fields, ok := structFields[fn.recvTypeName]; ok {
			// Build fields struct
			var sb strings.Builder
			sb.WriteString("\ttype fields struct {\n")
