	hasErr := hasError

	// For testify, we will have different handling, but for now normal

	// For writer with error case, the error handling is first, then want checks, then wantW checks

	// Example: Foo(w io.Writer) (int, error) with writer and error: test struct has want int, wantW string, wantErr bool; call is `got, err := Foo(w)` where w is buffer, then if error check, then if got != want, then if gotW != wantW

	// We need to generate that.

	// Build assignment line
	var assignLeft []string
	var gotVars []string // for non-error returns, the got variables
	for i := 0; i < numNonErr; i++ {
		if numNonErr == 1 {
			gotVars = append(gotVars, "got")
			assignLeft = append(assignLeft, "got")
		} else {
			// For multiple, got, got1, got2 ...
			if i == 0 {
				gotVars = append(gotVars, "got")
				assignLeft = append(assignLeft, "got")
			} else {
				gotVars = append(gotVars, fmt.Sprintf("got%d", i))
				assignLeft = append(assignLeft, fmt.Sprintf("got%d", i))
			}
		}
	}
	if hasErr {
		assignLeft = append(assignLeft, "err")
	}

	var callLine string
	if len(assignLeft) == 0 {
		// No results, just call
		callLine = fmt.Sprintf("%s%s", indent, callStr)
	} else if len(assignLeft) == 1 && assignLeft[0] == "err" {
		// Only error
		callLine = fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr)
		// For only error, the check is one-liner with t.Errorf inside?
		// Original: `if err := Foo(); (err != nil) != tt.wantErr { t.Errorf(...) }`
		// So we need to handle this case specially

		// We'll generate this directly
	} else {
		// Has got vars and possibly err
		left := strings.Join(assignLeft, ", ")
		callLine = fmt.Sprintf("%s%s := %s\n", indent, left, callStr)
		// But for case with error and got vars, it's `got, err := Foo(...)`

		// For case where assignLeft has only got (no err), it's `got := Foo(...)`
		// For multiple gots without err, it's `got, got1 := Foo(...)`
	}

	// We'll now write the body after call

	// Determine output based on hasError and numNonErr and nosubtests vs subtests

	// For simplicity, handle each case:

	// We need to handle testify vs normal vs go_cmp vs nosubtests vs parallel vs i etc.

	// Let's delegate to helper functions for each variant

	// Instead of trying to handle all in one place, we will create a helper that generates the body for normal mode with various flags

	// For now, let's call generateBody function

	body := generateBody(fn, callStr, gotVars, hasErr, numNonErr, wants, writerWants, resultTypes, resultIsError, resultNames, indent, hasReceiver, fieldsCode)

	sb.WriteString(body)

	// Close loops
	if *flagNosubtests {
		sb.WriteString("\t}\n")
	} else {
		sb.WriteString("\t\t})\n")
		sb.WriteString("\t}\n")
	}
	sb.WriteString("}\n")

	return sb.String()
}

func generateBody(fn funcInfo, callStr string, gotVars []string, hasErr bool, numNonErr int, wants []string, writerWants []string, resultTypes []string, resultIsError []bool, resultNames []string, indent string, hasReceiver bool, fieldsCode string) string {
	var sb strings.Builder
	// Determine if we are in testify mode - but this function is for normal mode only
	// For writer handling, the writer buffers already created above

	// For nosubtests, the error reporting uses %q. prefix or not? Let's see earlier:
	// - For normal with subtests, error is `t.Errorf("Foo() = %v, want %v", got, tt.want)` or with -i includes args
	// - For nosubtests, error is `t.Errorf("%q. Foo() = %v, want %v", tt.name, got, tt.want)`
	//   And for error check with nosubtests, it's `t.Errorf("%q. Foo() error = %v, wantErr %v", tt.name, err, tt.wantErr)` and `continue` instead of `return`

	// We need to handle all combinations of flags: -i, -nosubtests, -parallel, -named, -use_go_cmp, -template testify, etc.

	// For now implement normal (no testify, no go_cmp) with subtests and without nosubtests, with/without -i

	isTestify := *flagTemplate == "testify"
	useGoCmp := *flagUseGoCmp
	isNosub := *flagNosubtests
	// isParallel handled at top level, but inside loop also need handling
	// isI affects error message format
	isI := *flagI
	isNamed := *flagNamed

	// For testify, we need different body
	if isTestify {
		// Testify: for each case, use assert.Equal or assertion
		// Determine if function has error
		if hasErr {
			// For testify, test struct has assertion instead of wantErr
			// Call is `got, err := Foo(...); tt.assertion(t, err); assert.Equal(t, tt.want, got)`
			// For multiple wants, multiple asserts
			// Also writer handling: after call, check writer with assert.Equal

			// Build call line with got vars and err
			// gotVars already contains got, got1 etc., but we need to add err
			// For hasErr, gotVars length is numNonErr, and we need to add err

			// Example: Foo with int, error and writer: call `got, err := Foo(w, tt.args.a)` then `tt.assertion(t, err, fmt.Sprintf(...))` if -i else `tt.assertion(t, err)`
			// Then if not wantErr, check got vs want, then check writer

			// For hasErr, the call assignment includes err
			// For no hasErr, just got vars

			// Write call
			if numNonErr > 0 {
				left := strings.Join(append(gotVars, "err"), ", ")
				sb.WriteString(fmt.Sprintf("%sgot, err := %s\n", indent, strings.Join([]string{strings.Join(gotVars, ", "), "err"}, ", ")))
				// Actually need to handle numNonErr==1 vs multiple
				// Let's construct correctly
				var leftParts []string
				for i := 0; i < numNonErr; i++ {
					if i == 0 {
						leftParts = append(leftParts, "got")
					} else {
						leftParts = append(leftParts, fmt.Sprintf("got%d", i))
					}
				}
				leftParts = append(leftParts, "err")
				leftStr := strings.Join(leftParts, ", ")
				sb.WriteString(fmt.Sprintf("%s%s := %s\n", indent, leftStr, callStr))
				// Assertion
				if isI {
					// Need to print test inputs in error via fmt.Sprintf
					// For testify with -i, the assertion and Equal use fmt.Sprintf with args
					// Example: `tt.assertion(t, err, fmt.Sprintf("Foo(%v, %v)", tt.args.a, tt.args.b))`
					// And `assert.Equalf(t, tt.want, got, "Foo(%v, %v)", tt.args.a, tt.args.b)`
					// Need to get args for fmt
					// For writer case, args exclude writer params, but the fmt should include writer's buffer string? In earlier writer with -i, it had `t.Fatalf("Foo(%v) error = %v, wantErr %v", tt.args.w, err, tt.wantErr)`? Wait that was normal mode with writer and -i? Let's see earlier with writer and -i: it had `tt.args.w`? Actually for TakesWriter with -i, the error for wantW check had `tt.args.w`? The writer param is not in args, it's w buffer, but -i still prints `tt.args.w`? Let's see earlier: with -i and writer, the wantW check had `t.Errorf("Foo(%v, %v) = %v, want %v", tt.args.w, tt.args.a, gotW, tt.wantW)` where both w and a are printed? But w is not in args, it's buffer. However earlier we saw for writer with -i, the error check included `tt.args.w`? Let's check previous: For Foo(w io.Writer, a int) (int, error) with -i, the struct was `wantW string` and `want int` etc., and the error checks had `tt.args.w`? Actually that output had `tt.args.w` for writer? Let's re-run quickly.

				}
			} else {
				// Only error, no got
				sb.WriteString(fmt.Sprintf("%serr := %s\n", indent, callStr))
				// But for testify, if only error, the assertion still?
			}
			// For testify with writer and error, need to handle writer wantW after assertion
			// Simplified: just write generic

			sb.WriteString(fmt.Sprintf("%stt.assertion(t, err)\n", indent))
			for i := 0; i < numNonErr; i++ {
				gotVar := "got"
				if i > 0 {
					gotVar = fmt.Sprintf("got%d", i)
				}
				wantField := "tt.want"
				if i > 0 {
					wantField = fmt.Sprintf("tt.want%d", i)
				}
				sb.WriteString(fmt.Sprintf("%sassert.Equal(t, %s, %s)\n", indent, wantField, gotVar))
			}
			// Writer checks
			for i := range writerWants {
				varName := "w"
				if len(writerWants) > 1 {
					varName = fmt.Sprintf("w%d", i+1)
				}
				wantName := "tt.wantW"
				if len(writerWants) > 1 {
					wantName = fmt.Sprintf("tt.wantW%d", i+1)
				}
				sb.WriteString(fmt.Sprintf("%sassert.Equal(t, %s, %s.String())\n", indent, wantName, varName))
			}
		} else {
			// No error
			if numNonErr == 0 {
				// No return values, just call and maybe writer check
				sb.WriteString(fmt.Sprintf("%s%s\n", indent, callStr))
				for i := range writerWants {
					varName := "w"
					if len(writerWants) > 1 {
						varName = fmt.Sprintf("w%d", i+1)
					}
					wantName := "tt.wantW"
					if len(writerWants) > 1 {
						wantName = fmt.Sprintf("tt.wantW%d", i+1)
					}
					sb.WriteString(fmt.Sprintf("%sassert.Equal(t, %s, %s.String())\n", indent, wantName, varName))
