					}
				}
				leftStr := strings.Join(leftParts, ", ")
				if len(leftParts) == 1 {
					sb.WriteString(fmt.Sprintf("%sgot := %s\n", indent, callStr))
				} else {
					sb.WriteString(fmt.Sprintf("%s%s := %s\n", indent, leftStr, callStr))
				}
				for i := 0; i < numNonErr; i++ {
					gotVar := "got"
					if i > 0 {
						gotVar = fmt.Sprintf("got%d", i)
					}
					wantField := "tt.want"
					if i > 0 {
						wantField = fmt.Sprintf("tt.want%d", i)
					}
					sb.WriteString(fmt.Sprintf("%sassert.Equal(t, %s, %s)\n", indent, wantField, gotVar))
				}
				for i := range writerWants {
					varName := "w"
					if len(writerWants) > 1 {
						varName = fmt.Sprintf("w%d", i+1)
					}
					wantName := "tt.wantW"
					if len(writerWants) > 1 {
						wantName = fmt.Sprintf("tt.wantW%d", i+1)
					}
					sb.WriteString(fmt.Sprintf("%sassert.Equal(t, %s, %s.String())\n", indent, wantName, varName))
				}
			}
		}
		return sb.String()
	}

	// Normal mode (non-testify)

	// Handle error-only case specially
	if numNonErr == 0 && hasErr && len(writerWants) == 0 {
		// Only error return, no writer, no other returns
		if isNosub {
			// nosubtests: `if err := Foo(...); (err != nil) != tt.wantErr { t.Errorf("%q. Foo() error = %v, wantErr %v", tt.name, err, tt.wantErr) }`
			callArgsStr := strings.TrimPrefix(callStr, fn.name)
			// But callStr already includes full call, we need to reconstruct with if
			// For nosubtests, the call is inside if condition
			// Example: `if err := Foo(tt.args.a); (err != nil) != tt.wantErr { t.Errorf(...) }`
			// So we shouldn't have previous callLine
			// We'll generate directly
			// Need to get call without assignment? Actually for error only, call is `Foo(args)` returning error
			// So if condition is `if err := Foo(...); (err != nil) != tt.wantErr {`

			// Build args string for call
			// callStr is like `Foo(tt.args.a)` or `c.Method(...)`
			// For error only, we need `if err := Foo(...); (err != nil) != tt.wantErr {`

			if isI {
				// With -i, need to print inputs in error: `t.Errorf("%q. Foo(%v) error = %v, wantErr %v", tt.name, tt.args.a, err, tt.wantErr)`
				// Need to collect args for fmt: they are from nonWriterParams
				var fmtArgs []string
				for _, p := range fn.funcDecl.Type.Params.List {
					// Need to get param names
					// Simpler: use tt.args.<name> for each non-writer param
					if p.Type != nil && isWriterType(p.Type) {
						continue
					}
					for _, n := range p.Names {
						fmtArgs = append(fmtArgs, fmt.Sprintf("tt.args.%s", n.Name))
						if p.Type != nil {
