						}
					}
					if len(p.Names) == 0 {
						// anonymous
						// Need to generate in0 etc. But our fn's params handling already has names in0
						// For anonymous, the args field is in0, in1
						// This is getting too complex
					}
				}
				// For simplicity, if isI, generate with args
				fmtStr := "%q. Foo() error = %v, wantErr %v"
				if len(fmtArgs) > 0 {
					// Need to insert args into fmt string: "Foo(%v, %v)"
					fmtStr = "%q. Foo(" + strings.Repeat("%v, ", len(fmtArgs))
					fmtStr = strings.TrimSuffix(fmtStr, ", ") + ") error = %v, wantErr %v"
				}
				// But we need to get function name: for method, it's "S.Method()" etc.
				// Use fn.name with receiver
				funcPrintName := fn.name
				if hasReceiver {
					funcPrintName = fn.recvTypeName + "." + fn.name
				}
				if len(fmtArgs) > 0 {
					sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", tt.name", indent, fmtStr))
					for _, a := range fmtArgs {
						sb.WriteString(fmt.Sprintf(", %s", a))
					}
					sb.WriteString(", err, tt.wantErr)\n")
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				} else {
					sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s() error = %%v, wantErr %%v\", tt.name, err, tt.wantErr)\n", indent, funcPrintName))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				}
			} else {
				funcPrintName := fn.name
				if hasReceiver {
					funcPrintName = fn.recvTypeName + "." + fn.name
				}
				sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr))
				sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s() error = %%v, wantErr %%v\", tt.name, err, tt.wantErr)\n", indent, funcPrintName))
				sb.WriteString(fmt.Sprintf("%s}\n", indent))
			}
		} else {
			// With subtests
			if isI {
				// Need to include args in error message
				// For error only with -i, the error check is `if err := Foo(...); (err != nil) != tt.wantErr { t.Errorf("Foo(%v) error = %v, wantErr %v", tt.args.a, err, tt.wantErr) }`
				var fmtArgs []string
				// Collect non-writer param names
				// Use same as above
				for _, p := range gotVars {
					_ = p
				}
				// Simpler: iterate over nonWriterParams collected earlier? But we don't have them here
				// We can reconstruct from function decl
				var argsForFmt []string
				if fn.funcDecl.Type.Params != nil {
					for _, field := range fn.funcDecl.Type.Params.List {
						if isWriterType(field.Type) {
							continue
						}
						for _, n := range field.Names {
