							// For now, handle single anonymous
							// This is edge, but we can just use tt.args.in0
						}
					}
				}
				funcPrintName := fn.name
				if hasReceiver {
					funcPrintName = fn.recvTypeName + "." + fn.name
				}
				if len(argsForFmt) > 0 {
					fmtStr := funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
					fmtStr = strings.TrimSuffix(fmtStr, ", ") + ") error = %v, wantErr %v"
					sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", %s, err, tt.wantErr)\n", indent, fmtStr, strings.Join(argsForFmt, ", ")))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				} else {
					sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent, funcPrintName))
