			sb.WriteString(fmt.Sprintf("%s}\n", indent))
			sb.WriteString(fmt.Sprintf("%sif tt.wantErr {\n", indent))
			sb.WriteString(fmt.Sprintf("%s\treturn\n", indent))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
			for i := range writerWants {
				varName := "w"
				if len(writerWants) > 1 {
					varName = fmt.Sprintf("w%d", i+1)
				}
				wantName := "tt.wantW"
				if len(writerWants) > 1 {
					wantName = fmt.Sprintf("tt.wantW%d", i+1)
				}
				if isNosub {
					sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s() = %%v, want %%v\", tt.name, gotW, %s)\n", indent, funcPrintName, wantName))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				} else {
					if isI {
						// For writer with -i, the wantW check includes args? In earlier test with writer and -i, the wantW check had args? Let's see: For Foo(w, a int) with writer and -i, the wantW check had `t.Errorf("Foo(%v, %v) = %v, want %v", tt.args.w, tt.args.a, gotW, tt.wantW)`? Actually earlier we saw for writer with -i, the check was `t.Errorf("Foo(%v, %v) = %v, want %v", tt.args.w, tt.args.a, gotW, tt.wantW)` where both args are included. But tt.args.w doesn't exist because w is not in args. Wait earlier probe for writer with -i showed `tt.args.w`? Let's re-check: The earlier output for Foo(w io.Writer, a int) (int, error) with -i? It had `t.Errorf("Foo(%v) error = %v, wantErr %v", tt.args.w, err, tt.wantErr)`? That's weird because w is writer not in args, but they still printed tt.args.w?

						// Actually earlier we saw for writer with -i and error, the error check had `tt.args.w`? Let's look at previous capture: For Foo(w io.Writer) (int, error) with -i, the error check was `t.Fatalf("Foo(%v) error = %v, wantErr %v", tt.args.w, err, tt.wantErr)` - yes it included w.

						// So for writer params, the -i still prints them as tt.args.w? But w is not in args struct; it's a buffer. So how does tt.args.w exist? Wait for writer param case, the args struct does NOT contain w, so tt.args.w would be invalid.

						// Let's re-examine: For Foo(w io.Writer, a int) with writer, the args struct was `type args struct { a int }` without w, so tt.args.w would not exist. But the earlier output for writer with -i showed `tt.args.w`? Let's check that output again: It was

						// Generated TestFoo
						// ...
						// tests := []struct { name string; args args; want int; wantW string; wantErr bool }
						// ...
						// w := &bytes.Buffer{}
						// got, err := Foo(w, tt.args.a)
						// if (err != nil) != tt.wantErr { t.Fatalf("Foo(%v) error = %v, wantErr %v", tt.args.w, err, tt.wantErr) }

						// It did have tt.args.w even though args struct has no w field. That's a bug in original? But we must replicate bug.

						// Let's verify by re-running that test fresh.

					}
					sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", gotW, %s)\n", indent, funcPrintName, wantName))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				}
			}
		} else {
			// Subtests
			funcPrintName := fn.name
			if hasReceiver {
				funcPrintName = fn.recvTypeName + "." + fn.name
			}
			sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, callStr))
			sb.WriteString(fmt.Sprintf("%s\tt.Fatalf(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent, funcPrintName))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
			sb.WriteString(fmt.Sprintf("%sif tt.wantErr {\n", indent))
			sb.WriteString(fmt.Sprintf("%s\treturn\n", indent))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
			for i := range writerWants {
				varName := "w"
				if len(writerWants) > 1 {
					varName = fmt.Sprintf("w%d", i+1)
				}
				wantName := "tt.wantW"
				if len(writerWants) > 1 {
					wantName = fmt.Sprintf("tt.wantW%d", i+1)
				}
				sb.WriteString(fmt.Sprintf("%sif gotW := %s.String(); gotW != %s {\n", indent, varName, wantName))
				sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() = %%v, want %%v\", gotW, %s)\n", indent, funcPrintName, wantName))
				sb.WriteString(fmt.Sprintf("%s}\n", indent))
			}
		}
