			fmt.Printf("output.Process: loading custom templates: ioutil.ReadDir: open %s: no such file or directory", *flagTemplateDir)
			return
		}
	}
	if *flagTemplate != "" && *flagTemplate != "testify" && *flagTemplateDir == "" {
		fmt.Printf("output.Process: loading custom templates of name: templates.ParseFS: template: pattern matches no files: `*.tmpl`")
		return
	}
	if *flagAI {
		fmt.Printf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s", *flagAIEndpoint)
		return
	}
	var onlyRE, exclRE *regexp.Regexp
	var err error
	if *flagOnly != "" {
		onlyRE, err = regexp.Compile(*flagOnly)
		if err != nil {
			fmt.Printf("Invalid -only regex: %v", err)
			return
		}
	}
	if *flagExcl != "" {
		exclRE, err = regexp.Compile(*flagExcl)
		if err != nil {
			fmt.Printf("Invalid -excl regex: %v", err)
			return
		}
	}
	args := flag.Args()
	expanded := []string{}
	for _, p := range args {
		if strings.HasSuffix(p, "/...") {
			base := strings.TrimSuffix(p, "/...")
			if base == "" || base == "." {
				base = "."
			}
			dirSet := map[string]bool{}
			filepath.WalkDir(base, func(path string, d fs.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if !d.IsDir() && strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
					dir := filepath.Dir(path)
					dirSet[dir] = true
				}
				return nil
			})
			var dirs []string
			for d := range dirSet {
				dirs = append(dirs, d)
			}
			sort.Strings(dirs)
			expanded = append(expanded, dirs...)
			if len(dirs) == 0 {
				expanded = append(expanded, p)
			}
		} else {
			expanded = append(expanded, p)
		}
	}
	for _, p := range expanded {
		if err := processPath(p, onlyRE, exclRE); err != nil {
			fmt.Println(err.Error())
		}
	}
}

func processPath(path string, onlyRE, exclRE *regexp.Regexp) error {
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory\n", path)
	}
	if info.IsDir() {
		return processDirectory(path, onlyRE, exclRE)
	}
	if strings.HasSuffix(path, ".go") {
		return processFiles([]string{path}, onlyRE, exclRE, false)
	}
	return fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory\n", path)
}

func processDirectory(dir string, onlyRE, exclRE *regexp.Regexp) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory\n", dir)
	}
	var goFiles []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go") {
			goFiles = append(goFiles, filepath.Join(dir, name))
		}
	}
	if len(goFiles) == 0 {
		fmt.Printf("No tests generated for %s", dir)
		return nil
	}
	sort.Strings(goFiles)
	if *flagW {
		for _, f := range goFiles {
			if err := processFiles([]string{f}, onlyRE, exclRE, true); err != nil {
				fmt.Println(err.Error())
			}
		}
		return nil
	}
	hasOutput := false
	for _, f := range goFiles {
		out, has, err := generateForFiles([]string{f}, goFiles, onlyRE, exclRE)
		if err != nil {
			fmt.Print(err.Error())
			continue
		}
		if has {
			fmt.Print(out)
			hasOutput = true
		}
	}
	if !hasOutput {
		fmt.Printf("No tests generated for %s", dir)
	}
	return nil
}

func processFiles(targets []string, onlyRE, exclRE *regexp.Regexp, fromDir bool) error {
	dir := filepath.Dir(targets[0])
	entries, _ := os.ReadDir(dir)
	var allGoFiles []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go") {
			allGoFiles = append(allGoFiles, filepath.Join(dir, name))
		}
	}
	out, has, err := generateForFiles(targets, allGoFiles, onlyRE, exclRE)
	if err != nil {
		fmt.Print(err.Error())
		return nil
	}
	if !has {
		fmt.Printf("No tests generated for %s", targets[0])
		return nil
	}
	if *flagW {
		// split Generated lines
		lines := strings.Split(out, "\n")
		var genLines []string
		var codeLines []string
		inCode := false
		for _, line := range lines {
			if strings.HasPrefix(line, "Generated ") {
				genLines = append(genLines, line)
			} else if strings.HasPrefix(line, "package ") {
				inCode = true
				codeLines = append(codeLines, line)
			} else if inCode {
				codeLines = append(codeLines, line)
			}
		}
		// Check existing file
		target := targets[0]
		outputFile := strings.TrimSuffix(target, ".go") + "_test.go"
		existing := ""
		if data, err := os.ReadFile(outputFile); err == nil {
			existing = string(data)
		}
		var finalCode string
		if existing != "" {
			merged, hasNew, merr := mergeWithExisting(existing, strings.Join(codeLines, "\n"), genLines, target)
			if merr != nil {
				fmt.Print(merr.Error())
				return nil
			}
			if !hasNew {
				fmt.Printf("No tests generated for %s", target)
				return nil
			}
			for _, g := range genLines {
				fmt.Println(g)
			}
			finalCode = merged
		} else {
			for _, g := range genLines {
				if strings.TrimSpace(g) != "" {
					fmt.Println(g)
				}
			}
			finalCode = strings.Join(codeLines, "\n")
		}
		formatted, ferr := format.Source([]byte(finalCode))
		if ferr != nil {
			os.WriteFile(outputFile, []byte(finalCode), 0644)
		} else {
			os.WriteFile(outputFile, formatted, 0644)
		}
	} else {
		fmt.Print(out)
	}
	return nil
}

func generateForFiles(targets []string, allFiles []string, onlyRE, exclRE *regexp.Regexp) (string, bool, error) {
	fset := token.NewFileSet()
	fileMap := map[string]*ast.File{}
	for _, fname := range allFiles {
		src, err := os.ReadFile(fname)
		if err != nil {
			continue
		}
		f, err := parser.ParseFile(fset, fname, src, parser.ParseComments)
		if err != nil {
			isTarget := false
			for _, t := range targets {
				if t == fname {
					isTarget = true
				}
			}
			if isTarget {
				return "", false, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %s:%v\n", fname, err)
			} else {
				return "", false, fmt.Errorf("Parser.Parse source file: other file parser.ParseFile: %s:%v\n", fname, err)
			}
		}
		fileMap[fname] = f
	}
	var pkgName string
	for _, t := range targets {
		if f, ok := fileMap[t]; ok {
			pkgName = f.Name.Name
			break
		}
	}
	if pkgName == "" {
		for _, t := range targets {
			src, err := os.ReadFile(t)
			if err != nil {
				continue
			}
			f, err := parser.ParseFile(fset, t, src, parser.ParseComments)
			if err != nil {
				return "", false, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %s:%v\n", t, err)
			}
			pkgName = f.Name.Name
			fileMap[t] = f
			break
		}
	}
	typeDecls := map[string]ast.Expr{}
	structFields := map[string][]*ast.Field{}
	for _, f := range fileMap {
		for _, decl := range f.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.TYPE {
				continue
			}
			for _, spec := range gen.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				name := ts.Name.Name
				typeDecls[name] = ts.Type
				if st, ok := ts.Type.(*ast.StructType); ok && st.Fields != nil {
					structFields[name] = st.Fields.List
				}
			}
		}
	}
	type funcInfo struct {
		name         string
		recv         *ast.Field
		recvTypeName string
		recvIsPtr    bool
		funcDecl     *ast.FuncDecl
		file         *ast.File
		filename     string
	}
	var funcs []funcInfo
	for _, target := range targets {
		f, ok := fileMap[target]
		if !ok {
			src, err := os.ReadFile(target)
			if err != nil {
				continue
			}
			parsed, err := parser.ParseFile(fset, target, src, parser.ParseComments)
			if err != nil {
				return "", false, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %s:%v\n", target, err)
			}
			f = parsed
			fileMap[target] = f
		}
		for _, decl := range f.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			name := fd.Name.Name
			var recv *ast.Field
			var recvTypeName string
			var recvIsPtr bool
			if fd.Recv != nil && len(fd.Recv.List) > 0 {
				recv = fd.Recv.List[0]
				recvTypeExpr := recv.Type
				recvIsPtr = false
				if star, ok := recvTypeExpr.(*ast.StarExpr); ok {
					recvIsPtr = true
					recvTypeExpr = star.X
				}
				switch t := recvTypeExpr.(type) {
				case *ast.Ident:
					recvTypeName = t.Name
				case *ast.IndexExpr:
					if ident, ok := t.X.(*ast.Ident); ok {
						recvTypeName = ident.Name
					}
				case *ast.IndexListExpr:
					if ident, ok := t.X.(*ast.Ident); ok {
						recvTypeName = ident.Name
					}
				default:
					recvTypeName = fmt.Sprintf("%v", recvTypeExpr)
				}
			}
			funcs = append(funcs, funcInfo{name: name, recv: recv, recvTypeName: recvTypeName, recvIsPtr: recvIsPtr, funcDecl: fd, file: f, filename: target})
		}
	}
	filtered := []funcInfo{}
	for _, fn := range funcs {
		keep := false
		if exclRE != nil {
			if exclRE.MatchString(fn.name) {
				continue
			}
			if *flagOnly != "" {
				if onlyRE.MatchString(fn.name) {
					keep = true
				}
			} else if *flagExported {
				if isExported(fn.name) {
					keep = true
				}
			} else if *flagAll {
				keep = true
			} else {
				keep = true
			}
			if keep {
				filtered = append(filtered, fn)
			}
			continue
		}
		if *flagExported {
			if isExported(fn.name) {
				filtered = append(filtered, fn)
			}
			continue
		}
		if *flagOnly != "" {
			if onlyRE.MatchString(fn.name) {
				filtered = append(filtered, fn)
			}
			continue
		}
		if *flagAll {
			filtered = append(filtered, fn)
			continue
		}
	}
	if len(filtered) == 0 {
		return "", false, nil
	}
	existing := map[string]bool{}
	for _, fn := range filtered {
		testFile := strings.TrimSuffix(fn.filename, ".go") + "_test.go"
		if _, err := os.Stat(testFile); err == nil {
			data, err := os.ReadFile(testFile)
			if err == nil {
				fset2 := token.NewFileSet()
				f, err := parser.ParseFile(fset2, testFile, data, parser.ParseComments)
				if err != nil {
					return "", false, fmt.Errorf("Parser.Parse test file: target parser.ParseFile(): %s:%v\n", testFile, err)
				}
				for _, decl := range f.Decls {
					if fd, ok := decl.(*ast.FuncDecl); ok && strings.HasPrefix(fd.Name.Name, "Test") {
						existing[fd.Name.Name] = true
					}
				}
			}
		}
	}
	var newFuncs []funcInfo
	for _, fn := range filtered {
		tn := funcTestName(fn)
		if existing[tn] {
			continue
		}
		newFuncs = append(newFuncs, fn)
	}
	if len(newFuncs) == 0 {
		return "", false, nil
	}
	filtered = newFuncs
	sourceImports := map[string]string{}
	for _, f := range fileMap {
		for _, imp := range f.Imports {
			path := strings.Trim(imp.Path.Value, `"`)
			var name string
			if imp.Name != nil {
				name = imp.Name.Name
			} else {
				parts := strings.Split(path, "/")
				name = parts[len(parts)-1]
			}
			sourceImports[path] = name
		}
	}
	needReflect := false
	needBytes := false
	needCmp := false
	needTestify := false
	for _, fn := range filtered {
		hasWriter := hasWriterParam(fn.funcDecl)
		if hasWriter {
			needBytes = true
		}
		if fn.funcDecl.Type.Results != nil {
			for _, field := range fn.funcDecl.Type.Results.List {
				typStr := exprString(field.Type)
				if needsReflect(typStr, typeDecls) {
					if *flagTemplate == "testify" {
						needTestify = true
					} else if *flagUseGoCmp {
						needCmp = true
					} else {
						needReflect = true
					}
				}
			}
		}
		if *flagTemplate == "testify" {
			needTestify = true
		}
	}
	usedImports := map[string]bool{}
	for _, fn := range filtered {
		collectImports(fn.funcDecl, sourceImports, usedImports)
		if fn.recv != nil {
			if fields, ok := structFields[fn.recvTypeName]; ok {
				for _, field := range fields {
					collectImportFromExpr(field.Type, sourceImports, usedImports)
				}
			}
		}
	}
	var importLines []string
	importLines = append(importLines, `"testing"`)
	if needReflect {
		importLines = append(importLines, `"reflect"`)
	}
	if needBytes {
		importLines = append(importLines, `"bytes"`)
	}
	if needCmp {
		importLines = append(importLines, `"github.com/google/go-cmp/cmp"`)
	}
	if needTestify {
		importLines = append(importLines, `"github.com/stretchr/testify/assert"`)
	}
	for path, alias := range sourceImports {
		if path == "testing" {
			continue
		}
		if alias == "_" || alias == "." {
			if alias == "_" {
				importLines = append(importLines, fmt.Sprintf(`_ "%s"`, path))
			} else {
				importLines = append(importLines, fmt.Sprintf(`. "%s"`, path))
			}
			continue
		}
		if usedImports[path] {
			already := false
			for _, l := range importLines {
				if strings.Contains(l, `"`+path+`"`) {
					already = true
				}
			}
			if !already {
				base := filepath.Base(path)
				if alias != base {
					importLines = append(importLines, fmt.Sprintf(`%s "%s"`, alias, path))
				} else {
					importLines = append(importLines, fmt.Sprintf(`"%s"`, path))
				}
			}
		}
	}
	sort.Strings(importLines)
	var buf bytes.Buffer
	for _, fn := range filtered {
		fmt.Fprintf(&buf, "Generated %s\n", funcTestName(fn))
	}
	fmt.Fprintf(&buf, "package %s\n\n", pkgName)
	if len(importLines) > 0 {
		if len(importLines) == 1 {
			fmt.Fprintf(&buf, "import %s\n\n", importLines[0])
		} else {
			fmt.Fprintf(&buf, "import (\n")
			for _, imp := range importLines {
				fmt.Fprintf(&buf, "\t%s\n", imp)
			}
			fmt.Fprintf(&buf, ")\n\n")
		}
	}
	for _, fn := range filtered {
		testCode := generateTestFunction(fn, typeDecls, structFields, fileMap)
		buf.WriteString(testCode)
		buf.WriteString("\n")
	}
	src := buf.Bytes()
	content := string(src)
	lines := strings.Split(content, "\n")
	var genLines []string
	var codeStart int
	for i, line := range lines {
		if strings.HasPrefix(line, "Generated ") {
			genLines = append(genLines, line)
		} else if strings.HasPrefix(line, "package ") {
			codeStart = i
			break
		}
	}
	codePart := strings.Join(lines[codeStart:], "\n")
	formatted, err := format.Source([]byte(codePart))
	if err != nil {
		return "", false, fmt.Errorf("output.Process: imports.Process: /tmp/gotests_%d:%v\n", os.Getpid(), err)
	}
	var outBuf bytes.Buffer
	for _, g := range genLines {
		outBuf.WriteString(g)
		outBuf.WriteString("\n")
	}
	outBuf.Write(formatted)
	return outBuf.String(), true, nil
}

func funcTestName(fn funcInfo) string {
type funcInfo struct {
	name         string
	recv         *ast.Field
	recvTypeName string
	recvIsPtr    bool
	funcDecl     *ast.FuncDecl
	file         *ast.File
	filename     string
}
GO
"}

