func processPath(path string, onlyRE, exclRE *regexp.Regexp) error {
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory\n", path)
	}
	if info.IsDir() {
		return processDirectory(path, onlyRE, exclRE)
	}
	if strings.HasSuffix(path, ".go") {
		return processFiles([]string{path}, onlyRE, exclRE, false)
	}
	return fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory\n", path)
}

func processDirectory(dir string, onlyRE, exclRE *regexp.Regexp) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory\n", dir)
	}
	var goFiles []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go") {
			goFiles = append(goFiles, filepath.Join(dir, name))
		}
	}
	if len(goFiles) == 0 {
		fmt.Printf("No tests generated for %s", dir)
		return nil
	}
	sort.Strings(goFiles)
	if *flagW {
		for _, f := range goFiles {
			if err := processFiles([]string{f}, onlyRE, exclRE, true); err != nil {
				fmt.Println(err.Error())
			}
		}
		return nil
	}
	hasOutput := false
	for _, f := range goFiles {
		out, has, err := generateForFiles([]string{f}, goFiles, onlyRE, exclRE)
		if err != nil {
			fmt.Print(err.Error())
			continue
		}
		if has {
			fmt.Print(out)
			hasOutput = true
		}
	}
	if !hasOutput {
		fmt.Printf("No tests generated for %s", dir)
	}
	return nil
}

func processFiles(targets []string, onlyRE, exclRE *regexp.Regexp, fromDir bool) error {
