		if has {
			fmt.Print(out)
			hasOutput = true
		}
	}
	if !hasOutput {
		fmt.Printf("No tests generated for %s", dir)
	}
	return nil
}

func processFiles(targets []string, onlyRE, exclRE *regexp.Regexp) error {
	dir := filepath.Dir(targets[0])
	entries, _ := os.ReadDir(dir)
	var allGoFiles []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go") {
			allGoFiles = append(allGoFiles, filepath.Join(dir, name))
		}
	}
	out, has, err := generateForFiles(targets, allGoFiles, onlyRE, exclRE)
	if err != nil {
		fmt.Print(err.Error())
		return nil
	}
	if !has {
		fmt.Printf("No tests generated for %s", targets[0])
		return nil
	}
	if *flagW {
		lines := strings.Split(out, "\n")
		var genLines []string
		var codeLines []string
		inCode := false
		for _, line := range lines {
			if strings.HasPrefix(line, "Generated ") {
				genLines = append(genLines, line)
			} else if strings.HasPrefix(line, "package ") {
				inCode = true
				codeLines = append(codeLines, line)
			} else if inCode {
				codeLines = append(codeLines, line)
			}
		}
		target := targets[0]
		outputFile := strings.TrimSuffix(target, ".go") + "_test.go"
		existing := ""
		if data, err := os.ReadFile(outputFile); err == nil {
			existing = string(data)
		}
		var finalCode string
		if existing != "" {
			merged, hasNew, merr := mergeWithExisting(existing, strings.Join(codeLines, "\n"), genLines, target)
			if merr != nil {
				fmt.Print(merr.Error())
				return nil
			}
			if !hasNew {
				fmt.Printf("No tests generated for %s", target)
				return nil
			}
			for _, g := range genLines {
				fmt.Println(g)
			}
			finalCode = merged
		} else {
			for _, g := range genLines {
				if strings.TrimSpace(g) != "" {
					fmt.Println(g)
				}
			}
			finalCode = strings.Join(codeLines, "\n")
		}
		formatted, ferr := format.Source([]byte(finalCode))
		if ferr != nil {
			os.WriteFile(outputFile, []byte(finalCode), 0644)
		} else {
			os.WriteFile(outputFile, formatted, 0644)
		}
	} else {
		fmt.Print(out)
	}
	return nil
}

func funcTestName(fn funcInfo) string {
	if fn.recv != nil {
		return "Test" + fn.recvTypeName + "_" + fn.name
	}
	return "Test" + fn.name
}

func isExported(name string) bool {
	if name == "" {
		return false
	}
	return unicode.IsUpper(rune(name[0]))
}

func exprString(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.ArrayType:
		if t.Len == nil {
			return "[]" + exprString(t.Elt)
		}
		return "[" + exprString(t.Len) + "]" + exprString(t.Elt)
	case *ast.MapType:
		return "map[" + exprString(t.Key) + "]" + exprString(t.Value)
	case *ast.ChanType:
		return "chan " + exprString(t.Value)
	case *ast.FuncType:
		return "func()"
	case *ast.InterfaceType:
		return "interface{}"
	case *ast.StructType:
		return "struct{}"
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	case *ast.IndexExpr:
		return exprString(t.X) + "[" + exprString(t.Index) + "]"
	case *ast.IndexListExpr:
		return exprString(t.X) + "[" + exprString(t.Indices[0]) + "]"
	case *ast.Ellipsis:
		return "..." + exprString(t.Elt)
	case *ast.UnaryExpr:
		if t.Op == token.TILDE {
			return "~" + exprString(t.X)
		}
		return exprString(t.X)
	case *ast.BinaryExpr:
		return exprString(t.X) + " | " + exprString(t.Y)
	case *ast.ParenExpr:
		return exprString(t.X)
	default:
		return fmt.Sprintf("%T", expr)
	}
}

func needsReflect(typeStr string, typeDecls map[string]ast.Expr) bool {
	t := strings.TrimSpace(typeStr)
	if strings.HasPrefix(t, "*") {
		t = strings.TrimPrefix(t, "*")
		if t == "int" || t == "string" || t == "bool" || t == "float64" || t == "float32" || t == "int64" || t == "int32" || t == "uint" || t == "byte" || t == "rune" {
			return false
		}
		if decl, ok := typeDecls[t]; ok {
			if _, isStruct := decl.(*ast.StructType); isStruct {
				return true
			}
		}
		if strings.Contains(t, "[]") || strings.Contains(t, "map[") || strings.Contains(t, "chan") || strings.Contains(t, "func") {
			return true
		}
		if strings.Contains(t, "[") {
			base := strings.Split(t, "[")[0]
			if decl, ok := typeDecls[base]; ok {
				if _, isStruct := decl.(*ast.StructType); isStruct {
					return true
				}
			}
		}
		return true
	}
	if t == "int" || t == "string" || t == "bool" || t == "float64" || t == "float32" || t == "int64" || t == "int32" || t == "uint" || t == "byte" || t == "rune" || t == "error" {
		return false
	}
	if t == "error" {
		return false
	}
	if strings.HasPrefix(t, "~") {
		return false
	}
	if strings.HasPrefix(t, "[]") || strings.HasPrefix(t, "map[") || strings.HasPrefix(t, "chan ") || strings.HasPrefix(t, "func") || t == "interface{}" || strings.Contains(t, "interface") {
		return true
	}
	if strings.HasPrefix(t, "[") {
		return true
	}
	if decl, ok := typeDecls[t]; ok {
		if _, isStruct := decl.(*ast.StructType); isStruct {
			return true
		}
		if _, ok := decl.(*ast.InterfaceType); ok {
			return true
		}
	}
	if strings.Contains(t, "[") {
		base := strings.Split(t, "[")[0]
		if decl, ok := typeDecls[base]; ok {
			switch decl.(type) {
			case *ast.StructType:
				return true
			case *ast.InterfaceType:
				return true
			case *ast.ArrayType, *ast.MapType, *ast.ChanType, *ast.FuncType:
				return true
			}
		}
		return true
	}
	if strings.Contains(t, ".") {
		return true
	}
	if len(t) > 0 && unicode.IsUpper(rune(t[0])) {
		return true
	}
	return false
}

func hasWriterParam(fd *ast.FuncDecl) bool {
	if fd.Type.Params == nil {
		return false
	}
	for _, field := range fd.Type.Params.List {
		if isWriterType(field.Type) {
			return true
		}
	}
	return false
}

func isWriterType(expr ast.Expr) bool {
	switch t := expr.(type) {
	case *ast.SelectorExpr:
		if ident, ok := t.X.(*ast.Ident); ok {
			if ident.Name == "io" && t.Sel.Name == "Writer" {
				return true
			}
		}
	case *ast.StarExpr:
		return isWriterType(t.X)
	case *ast.ArrayType:
		return isWriterType(t.Elt)
	}
	return false
}

func collectImports(fd *ast.FuncDecl, sourceImports map[string]string, used map[string]bool) {
	if fd.Type.Params != nil {
		for _, field := range fd.Type.Params.List {
			collectImportFromExpr(field.Type, sourceImports, used)
		}
	}
	if fd.Type.Results != nil {
		for _, field := range fd.Type.Results.List {
			collectImportFromExpr(field.Type, sourceImports, used)
		}
	}
	if fd.Recv != nil {
		for _, field := range fd.Recv.List {
			collectImportFromExpr(field.Type, sourceImports, used)
		}
	}
}

func collectImportFromExpr(expr ast.Expr, sourceImports map[string]string, used map[string]bool) {
	switch t := expr.(type) {
	case *ast.SelectorExpr:
		if ident, ok := t.X.(*ast.Ident); ok {
			for path, alias := range sourceImports {
				if alias == ident.Name {
					used[path] = true
				}
			}
		}
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.StarExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.ArrayType:
		collectImportFromExpr(t.Elt, sourceImports, used)
		if t.Len != nil {
			collectImportFromExpr(t.Len, sourceImports, used)
		}
	case *ast.MapType:
		collectImportFromExpr(t.Key, sourceImports, used)
		collectImportFromExpr(t.Value, sourceImports, used)
	case *ast.ChanType:
		collectImportFromExpr(t.Value, sourceImports, used)
	case *ast.FuncType:
		if t.Params != nil {
			for _, f := range t.Params.List {
				collectImportFromExpr(f.Type, sourceImports, used)
			}
		}
		if t.Results != nil {
			for _, f := range t.Results.List {
				collectImportFromExpr(f.Type, sourceImports, used)
			}
		}
	case *ast.Ellipsis:
		collectImportFromExpr(t.Elt, sourceImports, used)
	case *ast.IndexExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		collectImportFromExpr(t.Index, sourceImports, used)
	case *ast.IndexListExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		for _, idx := range t.Indices {
			collectImportFromExpr(idx, sourceImports, used)
		}
	case *ast.BinaryExpr:
		collectImportFromExpr(t.X, sourceImports, used)
		collectImportFromExpr(t.Y, sourceImports, used)
	case *ast.UnaryExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	case *ast.ParenExpr:
		collectImportFromExpr(t.X, sourceImports, used)
	}
}

func generateForFiles(targets []string, allFiles []string, onlyRE, exclRE *regexp.Regexp) (string, bool, error) {
	fset := token.NewFileSet()
	fileMap := map[string]*ast.File{}
	for _, fname := range allFiles {
		src, err := os.ReadFile(fname)
		if err != nil {
			continue
		}
		f, err := parser.ParseFile(fset, fname, src, parser.ParseComments)
		if err != nil {
			isTarget := false
			for _, t := range targets {
				if t == fname {
					isTarget = true
				}
			}
			if isTarget {
				return "", false, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %s:%v\n", fname, err)
			} else {
				return "", false, fmt.Errorf("Parser.Parse source file: other file parser.ParseFile: %s:%v\n", fname, err)
			}
		}
		fileMap[fname] = f
	}
	var pkgName string
	for _, t := range targets {
		if f, ok := fileMap[t]; ok {
			pkgName = f.Name.Name
			break
		}
	}
	if pkgName == "" {
		for _, t := range targets {
			src, err := os.ReadFile(t)
			if err != nil {
				continue
			}
			f, err := parser.ParseFile(fset, t, src, parser.ParseComments)
			if err != nil {
				return "", false, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %s:%v\n", t, err)
			}
			pkgName = f.Name.Name
			fileMap[t] = f
			break
		}
	}
	typeDecls := map[string]ast.Expr{}
	structFields := map[string][]*ast.Field{}
	for _, f := range fileMap {
		for _, decl := range f.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.TYPE {
				continue
			}
			for _, spec := range gen.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				name := ts.Name.Name
				typeDecls[name] = ts.Type
				if st, ok := ts.Type.(*ast.StructType); ok && st.Fields != nil {
					structFields[name] = st.Fields.List
				}
			}
		}
	}
	var funcs []funcInfo
	for _, target := range targets {
		f, ok := fileMap[target]
		if !ok {
			src, err := os.ReadFile(target)
			if err != nil {
				continue
			}
			parsed, err := parser.ParseFile(fset, target, src, parser.ParseComments)
			if err != nil {
				return "", false, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %s:%v\n", target, err)
			}
			f = parsed
			fileMap[target] = f
		}
		for _, decl := range f.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			name := fd.Name.Name
			var recv *ast.Field
			var recvTypeName string
			var recvIsPtr bool
			if fd.Recv != nil && len(fd.Recv.List) > 0 {
				recv = fd.Recv.List[0]
				recvTypeExpr := recv.Type
				recvIsPtr = false
				if star, ok := recvTypeExpr.(*ast.StarExpr); ok {
					recvIsPtr = true
					recvTypeExpr = star.X
				}
				switch t := recvTypeExpr.(type) {
				case *ast.Ident:
					recvTypeName = t.Name
				case *ast.IndexExpr:
					if ident, ok := t.X.(*ast.Ident); ok {
						recvTypeName = ident.Name
					}
				case *ast.IndexListExpr:
					if ident, ok := t.X.(*ast.Ident); ok {
						recvTypeName = ident.Name
					}
				default:
					recvTypeName = fmt.Sprintf("%v", recvTypeExpr)
				}
			}
			funcs = append(funcs, funcInfo{name: name, recv: recv, recvTypeName: recvTypeName, recvIsPtr: recvIsPtr, funcDecl: fd, file: f, filename: target})
		}
	}
	filtered := []funcInfo{}
	for _, fn := range funcs {
		keep := false
		if exclRE != nil {
			if exclRE.MatchString(fn.name) {
				continue
			}
			if *flagOnly != "" {
				if onlyRE.MatchString(fn.name) {
					keep = true
				}
			} else if *flagExported {
				if isExported(fn.name) {
					keep = true
				}
			} else if *flagAll {
				keep = true
			} else {
				keep = true
			}
			if keep {
				filtered = append(filtered, fn)
			}
			continue
		}
		if *flagExported {
			if isExported(fn.name) {
				filtered = append(filtered, fn)
			}
			continue
		}
		if *flagOnly != "" {
			if onlyRE.MatchString(fn.name) {
				filtered = append(filtered, fn)
			}
			continue
		}
		if *flagAll {
			filtered = append(filtered, fn)
			continue
		}
	}
	if len(filtered) == 0 {
		return "", false, nil
	}
	existing := map[string]bool{}
	for _, fn := range filtered {
		testFile := strings.TrimSuffix(fn.filename, ".go") + "_test.go"
		if _, err := os.Stat(testFile); err == nil {
			data, err := os.ReadFile(testFile)
			if err == nil {
				fset2 := token.NewFileSet()
				f, err := parser.ParseFile(fset2, testFile, data, parser.ParseComments)
				if err != nil {
					return "", false, fmt.Errorf("Parser.Parse test file: target parser.ParseFile(): %s:%v\n", testFile, err)
				}
				for _, decl := range f.Decls {
					if fd, ok := decl.(*ast.FuncDecl); ok && strings.HasPrefix(fd.Name.Name, "Test") {
						existing[fd.Name.Name] = true
					}
				}
			}
		}
	}
	var newFuncs []funcInfo
	for _, fn := range filtered {
		tn := funcTestName(fn)
		if existing[tn] {
			continue
		}
		newFuncs = append(newFuncs, fn)
	}
	if len(newFuncs) == 0 {
		return "", false, nil
	}
	filtered = newFuncs
	sourceImports := map[string]string{}
	for _, f := range fileMap {
		for _, imp := range f.Imports {
			path := strings.Trim(imp.Path.Value, `"`)
			var name string
			if imp.Name != nil {
				name = imp.Name.Name
			} else {
				parts := strings.Split(path, "/")
				name = parts[len(parts)-1]
			}
			sourceImports[path] = name
		}
	}
	needReflect := false
	needBytes := false
	needCmp := false
	needTestify := false
	for _, fn := range filtered {
		hasWriter := hasWriterParam(fn.funcDecl)
		if hasWriter {
			needBytes = true
		}
		if fn.funcDecl.Type.Results != nil {
			for _, field := range fn.funcDecl.Type.Results.List {
				typStr := exprString(field.Type)
				if needsReflect(typStr, typeDecls) {
					if *flagTemplate == "testify" {
						needTestify = true
					} else if *flagUseGoCmp {
						needCmp = true
					} else {
						needReflect = true
					}
				}
			}
		}
		if *flagTemplate == "testify" {
			needTestify = true
		}
	}
	usedImports := map[string]bool{}
	for _, fn := range filtered {
		collectImports(fn.funcDecl, sourceImports, usedImports)
		if fn.recv != nil {
			if fields, ok := structFields[fn.recvTypeName]; ok {
				for _, field := range fields {
					collectImportFromExpr(field.Type, sourceImports, usedImports)
				}
			}
		}
	}
	var importLines []string
	importLines = append(importLines, `"testing"`)
	if needReflect {
		importLines = append(importLines, `"reflect"`)
	}
	if needBytes {
		importLines = append(importLines, `"bytes"`)
	}
	if needCmp {
		importLines = append(importLines, `"github.com/google/go-cmp/cmp"`)
	}
	if needTestify {
		importLines = append(importLines, `"github.com/stretchr/testify/assert"`)
	}
	for path, alias := range sourceImports {
		if path == "testing" {
			continue
		}
		if alias == "_" || alias == "." {
			if alias == "_" {
				importLines = append(importLines, fmt.Sprintf(`_ "%s"`, path))
			} else {
				importLines = append(importLines, fmt.Sprintf(`. "%s"`, path))
			}
			continue
		}
		if usedImports[path] {
			already := false
			for _, l := range importLines {
				if strings.Contains(l, `"`+path+`"`) {
					already = true
				}
			}
			if !already {
				base := filepath.Base(path)
				if alias != base {
					importLines = append(importLines, fmt.Sprintf(`%s "%s"`, alias, path))
				} else {
					importLines = append(importLines, fmt.Sprintf(`"%s"`, path))
				}
			}
		}
	}
	sort.Strings(importLines)
	var buf bytes.Buffer
	for _, fn := range filtered {
		fmt.Fprintf(&buf, "Generated %s\n", funcTestName(fn))
	}
	fmt.Fprintf(&buf, "package %s\n\n", pkgName)
	if len(importLines) > 0 {
		if len(importLines) == 1 {
			fmt.Fprintf(&buf, "import %s\n\n", importLines[0])
		} else {
			fmt.Fprintf(&buf, "import (\n")
			for _, imp := range importLines {
				fmt.Fprintf(&buf, "\t%s\n", imp)
			}
			fmt.Fprintf(&buf, ")\n\n")
		}
	}
	for _, fn := range filtered {
		testCode := generateTestFunction(fn, typeDecls, structFields, fileMap)
		buf.WriteString(testCode)
		buf.WriteString("\n")
	}
	src := buf.Bytes()
	content := string(src)
	lines := strings.Split(content, "\n")
	var genLines []string
	var codeStart int
	for i, line := range lines {
		if strings.HasPrefix(line, "Generated ") {
			genLines = append(genLines, line)
		} else if strings.HasPrefix(line, "package ") {
			codeStart = i
			break
		}
	}
	codePart := strings.Join(lines[codeStart:], "\n")
	formatted, err := format.Source([]byte(codePart))
	if err != nil {
		return "", false, fmt.Errorf("output.Process: imports.Process: /tmp/gotests_%d:%v\n", os.Getpid(), err)
	}
	var outBuf bytes.Buffer
	for _, g := range genLines {
		outBuf.WriteString(g)
		outBuf.WriteString("\n")
	}
	outBuf.Write(formatted)
	return outBuf.String(), true, nil
}

func mergeWithExisting(existing, newCode string, genLines []string, target string) (string, bool, error) {
	// Check duplicates already handled before, so assume has new
	// Just append functions
	// Extract functions from newCode (skip package and imports)
	lines := strings.Split(newCode, "\n")
	var funcsPart []string
	inFunc := false
	depth := 0
	for _, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "func Test") {
			inFunc = true
		}
		if inFunc {
			funcsPart = append(funcsPart, line)
		} else if strings.HasPrefix(strings.TrimSpace(line), "import") {
			// skip imports, already handled? Need to merge imports
			continue
		}
	}
	// For now, just append funcs to existing
	// Find import merging: if newCode needs imports not in existing, add them
	// Simplify: just append funcs and return existing + funcs
	merged := strings.TrimSpace(existing) + "\n\n" + strings.Join(funcsPart, "\n") + "\n"
	return merged, true, nil
}
