                        sb.WriteString(fmt.Sprintf("%s\\tt.Errorf(\\"%s() = %%v, want %%v\\", gotW, %s)\\n", indent, funcPrintName, wantName))
                        sb.WriteString(fmt.Sprintf("%s}\\n", indent))
                    }
                }
            }
        }
    }
    return sb.String()
}
