func mapConstraintToConcrete(expr ast.Expr, typeDecls map[string]ast.Expr) string {
    switch t := expr.(type) {
    case *ast.Ident:
        name := t.Name
        if name == "any" {
            return "int"
        }
        if name == "comparable" {
            return "string"
        }
        if decl, ok := typeDecls[name]; ok {
            if iface, ok := decl.(*ast.InterfaceType); ok {
                var terms []string
                if iface.Methods != nil {
                    for _, field := range iface.Methods.List {
                        if len(field.Names) == 0 {
                            terms = append(terms, exprString(field.Type))
                        }
                    }
                }
                if len(terms) == 0 {
                    return "string"
                }
                return "string"
            }
            return name
        }
        return name
    case *ast.BinaryExpr:
        if t.Op == token.OR {
            return mapConstraintToConcrete(t.X, typeDecls)
        }
        return "int"
    case *ast.UnaryExpr:
        if t.Op == token.TILDE {
            if ident, ok := t.X.(*ast.Ident); ok {
                return ident.Name
            }
            return exprString(t.X)
        }
        return exprString(t)
    case *ast.InterfaceType:
        if t.Methods != nil {
            for _, field := range t.Methods.List {
                if len(field.Names) == 0 {
                    return mapConstraintToConcrete(field.Type, typeDecls)
                }
            }
        }
        return "int"
    default:
        return "int"
    }
}

func replaceWord(s, old, new string) string {
    re := regexp.MustCompile(`\\b` + regexp.QuoteMeta(old) + `\\b`)
    return re.ReplaceAllString(s, new)
}

