func generateBody(fn funcInfo, callStr string, hasError bool, resultTypes []string, resultIsError []bool, resultNames []string, indent string, hasReceiver bool, fieldsCode string, writerWants []string) string {
    var sb strings.Builder
    isNosub := *flagNosubtests
    isI := *flagI
    useGoCmp := *flagUseGoCmp
    isTestify := *flagTemplate == "testify"
    numNonErr := 0
    for _, isErr := range resultIsError {
