    funcPrintName := fn.name
    if hasReceiver {
        funcPrintName = fn.recvTypeName + "." + fn.name
    }
    if isTestify {
        if hasError {
            if numNonErr > 0 {
                var leftParts []string
                for i := 0; i < numNonErr; i++ {
                    if i == 0 {
                        leftParts = append(leftParts, "got")
                    } else {
                        leftParts = append(leftParts, fmt.Sprintf("got%d", i))
                    }
                }
                leftParts = append(leftParts, "err")
                leftStr := strings.Join(leftParts, ", ")
                sb.WriteString(fmt.Sprintf("%s%s := %s\\n", indent, leftStr, callStr))
                if isI {
                    var argsForFmt []string
                    if fn.funcDecl.Type.Params != nil {
                        for _, field := range fn.funcDecl.Type.Params.List {
                            if isWriterType(field.Type) {
                                continue
                            }
                            for _, n := range field.Names {
                                argsForFmt = append(argsForFmt, fmt.Sprintf("tt.args.%s", n.Name))
                            }
                        }
                    }
                    if len(argsForFmt) > 0 {
                        fmtStr := funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
                        fmtStr = strings.TrimSuffix(fmtStr, ", ") + ")"
                        sb.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\\"%s\\", %s))\\n", indent, fmtStr, strings.Join(argsForFmt, ", ")))
                    } else {
                        sb.WriteString(fmt.Sprintf("%stt.assertion(t, err)\\n", indent))
                    }
                } else {
                    sb.WriteString(fmt.Sprintf("%stt.assertion(t, err)\\n", indent))
                }
                for i := 0; i < numNonErr; i++ {
                    gotVar := "got"
                    if i > 0 {
                        gotVar = fmt.Sprintf("got%d", i)
                    }
                    wantField := "tt.want"
                    if i > 0 {
                        wantField = fmt.Sprintf("tt.want%d", i)
                    }
                    if isI {
                        var argsForFmt []string
                        if fn.funcDecl.Type.Params != nil {
                            for _, field := range fn.funcDecl.Type.Params.List {
                                if isWriterType(field.Type) {
                                    continue
                                }
                                for _, n := range field.Names {
                                    argsForFmt = append(argsForFmt, fmt.Sprintf("tt.args.%s", n.Name))
                                }
                            }
                        }
                        if len(argsForFmt) > 0 {
                            fmtStr := funcPrintName + "(" + strings.Repeat("%v, ", len(argsForFmt))
                            fmtStr = strings.TrimSuffix(fmtStr, ", ") + ")"
