	hasOutput := false
	for _, f := range goFiles {
		out, has, err := generateForFiles([]string{f}, goFiles, onlyRE, exclRE)
		if err != nil {
			fmt.Print(err.Error())
			continue
		}
		if has {
			fmt.Print(out)
			hasOutput = true
		}
	}
	if !hasOutput {
		fmt.Printf("No tests generated for %s", dir)
	}
	return nil
}

func processFiles(targets []string, onlyRE, exclRE *regexp.Regexp) error {
